using System.Text.RegularExpressions;
using Meziantou.Framework.Imaging.TestHarness;
using Xunit.Sdk;

namespace Meziantou.Framework.Imaging.Tests.Documentation;

/// <summary>
/// Keeps the published C# examples compiled: every C# block of the published Markdown files (the package readme.md
/// of src/Meziantou.Framework.Imaging) must be generated by Meziantou.FileReferencer from a <c>#region</c> of the sample
/// sources, which are compiled by the samples project and by this test project (<see cref="DocumentationExampleTests"/>
/// runs them). FileReferencer's <c>--check</c> (run by <c>eng/update-all.cs</c>) verifies that the blocks are up to date.
/// </summary>
public sealed partial class DocumentationSnippetTests
{
    private const string EndMarker = "<!-- endref -->";

    private static readonly FullPath Root = RepositoryPaths.Root;

    private static readonly string[] PublishedMarkdownFiles = ["src/Meziantou.Framework.Imaging/readme.md"];

    public static TheoryData<string> MarkdownFiles => [.. PublishedMarkdownFiles];

    [Fact]
    public void PublishedMarkdownFilesExist()
    {
        Assert.All(PublishedMarkdownFiles, relativePath => Assert.True(File.Exists(Root / relativePath), $"{relativePath} does not exist."));
    }

    [Theory]
    [MemberData(nameof(MarkdownFiles))]
    public void CSharpBlocksAreGeneratedFromSamples(string relativePath)
    {
        var lines = File.ReadAllText(Root / relativePath).ReplaceLineEndings("\n").Split('\n');
        var blocks = 0;
        for (var i = 0; i < lines.Length; i++)
        {
            var fence = lines[i].TrimStart();
            if (!fence.StartsWith("```", StringComparison.Ordinal))
                continue;

            var end = FindClosingFence(lines, i, relativePath);
            if (IsCSharp(fence[3..].Trim()))
            {
                if (i == 0 || !SampleReferenceRegex().IsMatch(lines[i - 1].Trim()))
                    throw new XunitException($"{relativePath}:{i + 1}: a C# block must be generated from a region of samples/Meziantou.Framework.Imaging.Samples: replace it with '<!-- ref:../../samples/Meziantou.Framework.Imaging.Samples/<File>.cs;region=<Region>;format=md-fenced-code-block;dedent=true -->' and '{EndMarker}', then run 'dotnet run ./eng/update-all.cs -- --step snippets'.");

                if (end + 1 >= lines.Length || lines[end + 1].Trim() != EndMarker)
                    throw new XunitException($"{relativePath}:{end + 1}: the generated C# block must be followed by '{EndMarker}'.");

                blocks++;
            }

            i = end;
        }

        Assert.True(blocks > 0, $"{relativePath} has no C# block.");
    }

    private static bool IsCSharp(string language)
        => language.Equals("csharp", StringComparison.OrdinalIgnoreCase) || language.Equals("cs", StringComparison.OrdinalIgnoreCase) || language.Equals("c#", StringComparison.OrdinalIgnoreCase);

    private static int FindClosingFence(string[] lines, int start, string relativePath)
    {
        for (var i = start + 1; i < lines.Length; i++)
        {
            if (lines[i].Trim() == "```")
                return i;
        }

        throw new XunitException($"{relativePath}:{start + 1}: unterminated code block.");
    }

    [GeneratedRegex(@"^<!-- ref:\.\./\.\./samples/Meziantou\.Framework\.Imaging\.Samples/[A-Za-z0-9]+\.cs;region=Imaging_[A-Za-z0-9]+;format=md-fenced-code-block;dedent=true -->$", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: 1000)]
    private static partial Regex SampleReferenceRegex();
}
